{"files":[{"content":"#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

const int MOD = 1000000007;

int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<bool> > blockedCells(n, vector<bool>(n, false));
    for (int c = 0; c < m; c++) {
        int i, j;
        cin >> i >> j;
        blockedCells[i][j] = true;
    }

    if (n < 256) {
        vector<vector<int> > dp(2, vector<int>(n, 0));

        if (!blockedCells[0][0])
            dp[0][0] = 1;

        for (int j = 1; j < n; j++)
            if (!blockedCells[0][j]) dp[0][j] = dp[0][j - 1];
        dp[1][n - 1] = dp[0][n - 1];

        for (int i = 1; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int ans = 0;
                if (!blockedCells[i][j]) {
                    ans = dp[0][j];
                    if (j != 0) ans += dp[1][j - 1];
                }
                dp[1][j] = ans % MOD;
            }
            for (int j = 0; j < n; j++) dp[0][j] = dp[1][j];
        }

        cout << dp[1][n - 1] << endl;
        return 0;
    }

    vector<int> previous(n, 0), current(n, 0);
    if (!blockedCells[0][0]) previous[0] = 1;

    auto updateCell = [&](int row, int diagonal) {
        const int column = diagonal - row;
        if (blockedCells[row][column]) {
            current[row] = 0;
            return;
        }

        int value = 0;
        if (row > 0) value = previous[row - 1];
        if (column > 0) value += previous[row];
        if (value >= MOD) value -= MOD;
        current[row] = value;
    };

    #pragma omp parallel
    {
        for (int diagonal = 1; diagonal <= 2 * n - 2; diagonal++) {
            const int firstRow = max(0, diagonal - (n - 1));
            const int lastRow = min(n - 1, diagonal);

            #pragma omp for schedule(static)
            for (int row = firstRow; row <= lastRow; row++)
                updateCell(row, diagonal);

            #pragma omp single
            {
                previous.swap(current);
            }
        }
    }

    cout << previous[n - 1] << endl;
}
